公开定义.pointsFor:
pointsFor(e) {
        if (e.mode !== `tower` || !e.tower) return Qn(e);
        let t = e.tower,
          n = e.splits.length,
          r = Math.min(7, n) * 10,
          i = Math.max(0, n - 7) * 15 * (1 + 0.25 * t.curses.length),
          a = n < e.stage ? t.wave * 3 : 0;
        return Math.round(r + i + a + (t.marowak ? 25 : 0) + (t.won ? 60 : 0));
      }

公开定义.countersFor:
countersFor(e) {
        if (e.mode !== `tower` || !e.tower) return {};
        let t = e.tower;
        return {
          reveals: Math.min(t.reveals, e.kills + 50),
          tricks: Math.min(t.tricks, 3 * e.stage + 3),
          candles: t.candles,
          floor: e.stage,
          wins: +!!t.won,
          marowak: +!!t.marowak,
          dark4: t.offerings.includes(`dark4`) && e.splits.length >= 4 ? 1 : 0,
        };
      }

公开定义.boardValue:
boardValue(e) {
        return e.mode === `tower` && e.tower
          ? dn(e.stage, e.tower.wave, e.time)
          : null;
      }

