function so(e, t, n, r) {
  switch (n) {
    case `shiny`:
      return io(e, t, r);
    case `spectral`:
      return oo(e, t);
    case `classic`:
      return ii(e, t, r);
    case `m1`:
      return ri(e, t, 1);
    case `m2`:
      return ri(e, t, 2);
    case `t1`:
    case `t2`:
      return ni(e, t, n);
  }
}

availabilityRules.decodeSkin:
function Cr(e) {
  return !Number.isInteger(e) || e === 0
    ? null
    : e < 0
      ? e > -1e3
        ? { member: -e, look: `spectral` }
        : null
      : e < 1e3
        ? { member: e, look: `shiny` }
        : e < A[0]
          ? { member: e - xr, look: `classic` }
          : e < A[1]
            ? { member: e - A[0], look: `m1` }
            : e < A[1] + 1e3
              ? { member: e - A[1], look: `m2` }
              : e < j[0] + 1e3
                ? { member: e - j[0], look: `t1` }
                : e < j[1] + 1e3
                  ? { member: e - j[1], look: `t2` }
                  : null;
}

availabilityRules.normalizeTeam:
function co(e, t) {
  return !Array.isArray(t) || t.length > 40
    ? null
    : [
        ...new Set(
          t.filter((t) => Number.isInteger(t) && e.league.includes(t)),
        ),
      ].slice(0, 6);
}

avatarAvailabilityRules.validatorSource:
function xr(e, t, n) {
  if (t === ``) return !0;
  if (typeof t != `string` || t.length > 24) return !1;
  let [r, i] = t.split(`:`);
  if (r === `mon`) {
    if (/^\d+$/.test(i)) return vr(e, Number(i), n);
    if (/^\d+s$/.test(i)) return yr(e, parseInt(i, 10), n);
    let t = /^(\d+)([cab])$/.exec(i ?? ``);
    return (
      !!t &&
      n.has(Number(t[1])) &&
      Tr(e, Number(t[1]), br[t[2]], (e) => n.family(e))
    );
  }
  let a = dr.find((e) => e.id === i);
  return r !== `tr` || !a
    ? !1
    : a.research
      ? on(e, n).has(t)
      : !!a.free || e.cosmetics.includes(t);
}

